func TestViewFactoryCreate_NoConfiguredLocales(t *testing.T) {
	t.Parallel()

	f := newTestViewFactory(t, nil, nil)
	req := newTestRequest("/")

	view, err := f.Create(req, "page")
	if err != nil {
		t.Fatalf("Create() error = %v", err)
	}

	if len(view.model.LocaleOptions) != 0 {
		t.Fatalf("LocaleOptions length = %d, want 0", len(view.model.LocaleOptions))
	}

	wantLocale := LocaleOption{
		Locale:    localization.UndLocale,
		IsCurrent: true,
		URL:       "/",
	}
	if view.model.Locale != wantLocale {
		t.Errorf("Locale = %#v, want %#v", view.model.Locale, wantLocale)
	}

	if view.model.Translations != nil {
		t.Errorf("Translations = %#v, want nil", view.model.Translations)
	}
}

func TestViewFactoryCreate_ConfiguredLocales(t *testing.T) {
	t.Parallel()

	translations := localization.Store{
		"en": localization.Translations{"title": "Musings"},
		"ar": localization.Translations{"title": "Reflections"},
	}
	f := newTestViewFactory(t, []localization.Locale{viewTestEn, viewTestAr}, translations)
	req := newLocalizedTestRequest(t, []localization.Locale{viewTestEn, viewTestAr}, "/ar/posts", "/posts")

	view, err := f.Create(req, "page")
	if err != nil {
		t.Fatalf("Create() error = %v", err)
	}

	wantOptions := []LocaleOption{
		{
			Locale:    viewTestEn,
			IsCurrent: false,
			URL:       "/en/posts",
		},
		{
			Locale:    viewTestAr,
			IsCurrent: true,
			URL:       "/ar/posts",
		},
	}
	if !reflect.DeepEqual(view.model.LocaleOptions, wantOptions) {
		t.Errorf("LocaleOptions = %#v, want %#v", view.model.LocaleOptions, wantOptions)
	}

	if view.model.Locale != wantOptions[1] {
		t.Errorf("Locale = %#v, want %#v", view.model.Locale, wantOptions[1])
	}

	if !reflect.DeepEqual(view.model.Translations, translations["ar"]) {
		t.Errorf("Translations = %#v, want %#v", view.model.Translations, translations["ar"])
	}
}

func TestViewFactoryCreate_ConfiguredLocalesRootPath(t *testing.T) {
	t.Parallel()

	locales := []localization.Locale{viewTestEn, viewTestAr}
	f := newTestViewFactory(t, locales, nil)
	req := newLocalizedTestRequest(t, locales, "/en", "/")

	view, err := f.Create(req, "page")
	if err != nil {
		t.Fatalf("Create() error = %v", err)
	}

	wantURLs := []string{"/en/", "/ar/"}
	for i, want := range wantURLs {
		if got := view.model.LocaleOptions[i].URL; got != want {
			t.Errorf("LocaleOptions[%d].URL = %q, want %q", i, got, want)
		}
	}
}

