func TestViewFactoryCreate_Options(t *testing.T) {
	t.Parallel()

	f := newTestViewFactory(t, nil, nil)
	req := newTestRequest("/")
	dataModified := time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)
	data := struct{ Title string }{Title: "A post"}

	view, err := f.Create(req, "page",
		WithData(data),
		WithDataModified(dataModified),
	)
	if err != nil {
		t.Fatalf("Create() error = %v", err)
	}

	if view.model.Data != data {
		t.Errorf("Data = %#v, want %#v", view.model.Data, data)
	}
	if !view.modified.Equal(dataModified) {
		t.Errorf("modified = %v, want %v", view.modified, dataModified)
	}
}

