func TestViewServe(t *testing.T) {
	t.Parallel()

	f := newTestViewFactory(t, nil, nil)
	req := newTestRequest("/")
	view, err := f.Create(req, "page", WithData("served"))
	if err != nil {
		t.Fatalf("Create() error = %v", err)
	}

	rec := httptest.NewRecorder()
	if err := view.Serve(rec); err != nil {
		t.Fatalf("Serve() error = %v", err)
	}

	if got := rec.Header().Get("Content-Type"); got != "text/html; charset=utf-8" {
		t.Errorf("Content-Type = %q, want %q", got, "text/html; charset=utf-8")
	}

	wantModified := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC).Format(http.TimeFormat)
	if got := rec.Header().Get("Last-Modified"); got != wantModified {
		t.Errorf("Last-Modified = %q, want %q", got, wantModified)
	}

	if got := rec.Body.String(); got != "served" {
		t.Errorf("body = %q, want %q", got, "served")
	}
}

func newTestViewFactory(t *testing.T, locales []localization.Locale, translations localization.Store) *ViewFactory {
	t.Helper()

	store := templates.NewCachedStore()
	err := store.LoadFS(fstest.MapFS{
		"page.gohtml": {
			Data:    []byte(`{{.Data}}`),
			ModTime: time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC),
		},
	})
	if err != nil {
		t.Fatalf("LoadFS() error = %v", err)
	}

	return &ViewFactory{
		locales:       locales,
		templateStore: store,
		translations:  translations,
	}
}

func newTestRequest(routePath string) *http.Request {
	req := httptest.NewRequest(http.MethodGet, routePath, nil)
	return withRoutePath(req, routePath)
}

func newLocalizedTestRequest(t *testing.T, locales []localization.Locale, reqPath string, routePath string) *http.Request {
	t.Helper()

	req := withRoutePath(httptest.NewRequest(http.MethodGet, reqPath, nil), routePath)
	rec := httptest.NewRecorder()
	localized, ok := localization.NewLocalizedRouteMiddleware(locales).Handle(rec, req)
	if !ok {
		t.Fatalf("localized route was not accepted: status %d, location %q", rec.Code, rec.Header().Get("Location"))
	}
	return localized
}

func withRoutePath(req *http.Request, routePath string) *http.Request {
	chiCtx := chi.NewRouteContext()
	chiCtx.URLParams.Add("*", routePath)
	ctx := context.WithValue(req.Context(), chi.RouteCtxKey, chiCtx)
	return req.WithContext(ctx)
}
